using System;using System.IO;using System.IO.Compression;using System.Reflection;using System.Diagnostics;using System.Windows.Forms;using Microsoft.Win32;
class Installer{
[STAThread]static void Main(){Application.EnableVisualStyles();string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Nosotros","App");if(MessageBox.Show("Instalar NOSOTROS. para este usuario de Windows?\n\nIncluye calendario, listas, notas, fotos de perfil y widget. La vinculación por código requiere el servicio configurado.","NOSOTROS. | Instalación",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return;try{Directory.CreateDirectory(target);using(Stream stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(ZipArchive z=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var entry in z.Entries){string full=Path.GetFullPath(Path.Combine(target,entry.FullName));if(!full.StartsWith(target+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Ruta inválida");if(entry.Name.Length==0){Directory.CreateDirectory(full);continue;}Directory.CreateDirectory(Path.GetDirectoryName(full));using(var input=entry.Open())using(var output=File.Create(full))input.CopyTo(output);}}
string exe=Path.Combine(target,"Nosotros.exe");Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"NOSOTROS.lnk"),exe,target);Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"NOSOTROS.lnk"),exe,target);
string uninstaller=Path.Combine(target,"Desinstalar.cmd");File.WriteAllText(uninstaller,"@echo off\r\ncd /d %TEMP%\r\n del /q \"%USERPROFILE%\\Desktop\\NOSOTROS.lnk\" 2>nul\r\n del /q \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\NOSOTROS.lnk\" 2>nul\r\n reg delete HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Nosotros /f >nul 2>&1\r\n rmdir /s /q \""+target+"\"\r\n echo Los datos personales se conservan en LocalAppData\\Nosotros\\WebData.\r\n pause\r\n");
using(var k=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\Nosotros")){k.SetValue("DisplayName","NOSOTROS.");k.SetValue("DisplayVersion","0.3.0");k.SetValue("Publisher","NOSOTROS");k.SetValue("InstallLocation",target);k.SetValue("UninstallString","cmd.exe /c \""+uninstaller+"\"");k.SetValue("NoModify",1);k.SetValue("NoRepair",1);}
if(MessageBox.Show("Instalación completada. ¿Abrir NOSOTROS.?","NOSOTROS.",MessageBoxButtons.YesNo,MessageBoxIcon.Information)==DialogResult.Yes)Process.Start(new ProcessStartInfo(exe){WorkingDirectory=target});}catch(Exception e){MessageBox.Show("No se pudo instalar. Cierra NOSOTROS si está abierto e inténtalo de nuevo.\n"+e.Message,"Error",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
static void Shortcut(string path,string exe,string folder){var t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(path);link.TargetPath=exe;link.WorkingDirectory=folder;link.Description="Un espacio privado para dos";link.Save();}
}
